CREATE TABLE public.safety_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid REFERENCES public.listings(id), reporter_user_id uuid NOT NULL DEFAULT auth.uid(), category text NOT NULL CHECK(category IN ('urgent_danger','fire_electrical','water_sanitation','overcrowding','harassment_threat','billing_lease','accessibility','other')), urgency text NOT NULL DEFAULT 'normal', encrypted_description text NOT NULL CHECK(encrypted_description LIKE 'v1:%'), encrypted_contact text CHECK(encrypted_contact LIKE 'v1:%'), sharing_scope text NOT NULL CHECK(sharing_scope IN ('safety_staff_only','redacted_response_permitted')), notice_version text NOT NULL, consent_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','acknowledged','in_review','closed')), assigned_to uuid, acknowledged_at timestamptz, closed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.safety_cases TO authenticated;
GRANT ALL ON public.safety_cases TO service_role;
ALTER TABLE public.safety_cases ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.is_safety_staff() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.jwt()->>'aal'='aal2' AND public.has_role(auth.uid(),'safety_manager') $$;
CREATE POLICY "reporter own case" ON public.safety_cases FOR SELECT TO authenticated USING(reporter_user_id=auth.uid());
CREATE POLICY "reporter submits private case" ON public.safety_cases FOR INSERT TO authenticated WITH CHECK(reporter_user_id=auth.uid() AND status='new' AND assigned_to IS NULL AND notice_version='2026-10-27-v1');
CREATE POLICY "assigned safety staff read" ON public.safety_cases FOR SELECT TO authenticated USING(public.is_safety_staff() AND assigned_to=auth.uid());
CREATE POLICY "assigned safety staff update" ON public.safety_cases FOR UPDATE TO authenticated USING(public.is_safety_staff() AND assigned_to=auth.uid()) WITH CHECK(public.is_safety_staff() AND assigned_to=auth.uid());
CREATE TABLE public.safety_case_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES public.safety_cases(id), actor_id uuid NOT NULL DEFAULT auth.uid(), status text NOT NULL CHECK(status IN ('acknowledged','in_review','closed')), public_note text NOT NULL CHECK(length(public_note) BETWEEN 10 AND 1000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.safety_case_events TO authenticated;
GRANT ALL ON public.safety_case_events TO service_role;
ALTER TABLE public.safety_case_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "case events reporter or assigned" ON public.safety_case_events FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.safety_cases c WHERE c.id=case_id AND (c.reporter_user_id=auth.uid() OR (c.assigned_to=auth.uid() AND public.is_safety_staff()))));
CREATE POLICY "case events assigned staff" ON public.safety_case_events FOR INSERT TO authenticated WITH CHECK(actor_id=auth.uid() AND public.is_safety_staff() AND EXISTS(SELECT 1 FROM public.safety_cases c WHERE c.id=case_id AND c.assigned_to=auth.uid()));
CREATE OR REPLACE FUNCTION public.guard_safety_case() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN NEW.urgency=CASE WHEN NEW.category IN ('urgent_danger','fire_electrical','harassment_threat') THEN 'critical' WHEN NEW.category IN ('water_sanitation','overcrowding') THEN 'high' ELSE 'normal' END; ELSE NEW.encrypted_description=OLD.encrypted_description;NEW.encrypted_contact=OLD.encrypted_contact;NEW.reporter_user_id=OLD.reporter_user_id;NEW.sharing_scope=OLD.sharing_scope;NEW.category=OLD.category;NEW.urgency=OLD.urgency;NEW.listing_id=OLD.listing_id;NEW.notice_version=OLD.notice_version;NEW.consent_at=OLD.consent_at;NEW.updated_at=now(); END IF; RETURN NEW; END $$;
CREATE TRIGGER private_safety_case_guard BEFORE INSERT OR UPDATE ON public.safety_cases FOR EACH ROW EXECUTE FUNCTION public.guard_safety_case();
CREATE OR REPLACE FUNCTION public.safety_triage_queue() RETURNS TABLE(id uuid,category text,urgency text,created_at timestamptz,status text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c.id,c.category,c.urgency,c.created_at,c.status FROM public.safety_cases c WHERE public.is_safety_staff() AND c.assigned_to IS NULL ORDER BY c.created_at LIMIT 100 $$;
CREATE OR REPLACE FUNCTION public.claim_safety_case(_case uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_safety_staff() THEN RAISE EXCEPTION 'Assigned safety role and MFA required'; END IF; UPDATE public.safety_cases SET assigned_to=auth.uid() WHERE id=_case AND assigned_to IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Case already assigned'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.update_safety_case(_case uuid,_status text,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_safety_staff() OR NOT EXISTS(SELECT 1 FROM public.safety_cases WHERE id=_case AND assigned_to=auth.uid()) OR _status NOT IN ('acknowledged','in_review','closed') OR length(trim(_note)) NOT BETWEEN 10 AND 1000 THEN RAISE EXCEPTION 'Forbidden or invalid update'; END IF; INSERT INTO public.safety_case_events(case_id,status,public_note) VALUES(_case,_status,trim(_note)); UPDATE public.safety_cases SET status=_status,acknowledged_at=coalesce(acknowledged_at,now()),closed_at=CASE WHEN _status='closed' THEN now() ELSE NULL END WHERE id=_case; END $$;
REVOKE ALL ON FUNCTION public.safety_triage_queue(),public.claim_safety_case(uuid),public.update_safety_case(uuid,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.safety_triage_queue(),public.claim_safety_case(uuid),public.update_safety_case(uuid,text,text) TO authenticated;
CREATE POLICY "legacy reports restricted assigned" ON public.safety_reports AS RESTRICTIVE FOR SELECT TO authenticated USING(reporter_user_id=auth.uid() OR (assigned_to=auth.uid() AND public.is_safety_staff()));
COMMENT ON COLUMN public.safety_reports.description IS 'DEPRECATED: new reports use encrypted safety_cases; legacy plaintext needs reviewed retention and migration.';
CREATE OR REPLACE FUNCTION public.public_assurance_detail(_listing uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('last_audited_at',l.last_audited_at,'next_review_at',l.next_review_at,'verifications',coalesce((SELECT jsonb_agg(jsonb_build_object('type',v.verification_type,'authority',v.source_authority,'checked_at',v.checked_at,'expires_at',v.expires_at,'status',CASE WHEN v.expires_at<current_date THEN 'expired' ELSE 'confirmed' END)) FROM public.provider_verifications v WHERE v.listing_id=l.id AND v.status='confirmed'),'[]'::jsonb),'audits',coalesce((SELECT jsonb_agg(jsonb_build_object('type',a.audit_type,'completed_at',a.submitted_at,'next_due_at',a.next_due_at,'template_version',a.template_version)) FROM public.audits a WHERE a.listing_id=l.id AND a.decision='approved'),'[]'::jsonb),'actions',coalesce((SELECT jsonb_agg(jsonb_build_object('severity',c.severity,'status',c.status,'due_at',c.due_at)) FROM public.corrective_actions c WHERE c.listing_id=l.id AND c.public_disclosure_level<>'none' AND c.status<>'closed'),'[]'::jsonb),'utilities',coalesce((SELECT jsonb_agg(jsonb_build_object('type',u.utility_type,'started_at',u.started_at,'ended_at',u.ended_at,'summary',u.public_summary,'source',u.source)) FROM public.utility_events u WHERE u.listing_id=l.id AND u.confidence='verified'),'[]'::jsonb)) FROM public.listings l WHERE l.id=_listing AND l.status='approved' $$;
REVOKE ALL ON FUNCTION public.public_assurance_detail(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.public_assurance_detail(uuid) TO anon,authenticated;